#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_GCDS 32

typedef struct {
    int len;
    long long good;
    int plen, slen;
    int pg[MAX_GCDS], pc[MAX_GCDS];
    int sg[MAX_GCDS], sc[MAX_GCDS];
} Node;

static Node *tree;

static int gcd_int(int a, int b) {
    while (b != 0) {
        int t = a % b;
        a = b;
        b = t;
    }
    return a;
}

static void merge_nodes(const Node *a, const Node *b, Node *out) {
    out->len = a->len + b->len;

    long long cross = 0;
    int previous = 0;

    for (int i = 0; i < a->slen; i++) {
        int low = 0, high = b->plen;
        while (low < high) {
            int mid = low + (high - low) / 2;
            if (gcd_int(a->sg[i], b->pg[mid]) > 1)
                low = mid + 1;
            else
                high = mid;
        }

        int right_count = (low == 0) ? 0 : b->pc[low - 1];
        int left_count = a->sc[i] - previous;
        previous = a->sc[i];
        cross += (long long)left_count * right_count;
    }

    out->good = a->good + b->good + cross;

    out->plen = a->plen;
    for (int i = 0; i < a->plen; i++) {
        out->pg[i] = a->pg[i];
        out->pc[i] = a->pc[i];
    }

    previous = 0;
    for (int i = 0; i < b->plen; i++) {
        int value = gcd_int(a->pg[a->plen - 1], b->pg[i]);
        int cumulative = a->len + b->pc[i];

        if (out->pg[out->plen - 1] == value)
            out->pc[out->plen - 1] = cumulative;
        else {
            out->pg[out->plen] = value;
            out->pc[out->plen] = cumulative;
            out->plen++;
        }
        previous = b->pc[i];
    }

    out->slen = b->slen;
    for (int i = 0; i < b->slen; i++) {
        out->sg[i] = b->sg[i];
        out->sc[i] = b->sc[i];
    }

    previous = 0;
    for (int i = 0; i < a->slen; i++) {
        int value = gcd_int(b->sg[b->slen - 1], a->sg[i]);
        int cumulative = b->len + a->sc[i];

        if (out->sg[out->slen - 1] == value)
            out->sc[out->slen - 1] = cumulative;
        else {
            out->sg[out->slen] = value;
            out->sc[out->slen] = cumulative;
            out->slen++;
        }
        previous = a->sc[i];
    }
}

static void build(int node, int left, int right, const int *values) {
    if (left == right) {
        Node *cur = &tree[node];
        int value = values[left];

        cur->len = 1;
        cur->good = (value > 1);
        cur->plen = cur->slen = 1;
        cur->pg[0] = cur->sg[0] = value;
        cur->pc[0] = cur->sc[0] = 1;
        return;
    }

    int mid = left + (right - left) / 2;
    int left_child = node + 1;
    int right_child = node + 2 * (mid - left + 1);

    build(left_child, left, mid, values);
    build(right_child, mid + 1, right, values);
    merge_nodes(&tree[left_child], &tree[right_child], &tree[node]);
}

static void update(int node, int left, int right, int index, int value) {
    if (left == right) {
        Node *cur = &tree[node];
        cur->len = 1;
        cur->good = (value > 1);
        cur->plen = cur->slen = 1;
        cur->pg[0] = cur->sg[0] = value;
        cur->pc[0] = cur->sc[0] = 1;
        return;
    }

    int mid = left + (right - left) / 2;
    int left_child = node + 1;
    int right_child = node + 2 * (mid - left + 1);

    if (index <= mid)
        update(left_child, left, mid, index, value);
    else
        update(right_child, mid + 1, right, index, value);

    merge_nodes(&tree[left_child], &tree[right_child], &tree[node]);
}

static int query(int node, int left, int right, int ql, int qr, Node *out) {
    if (ql <= left && right <= qr) {
        memcpy(out, &tree[node], sizeof(Node));
        return 1;
    }

    int mid = left + (right - left) / 2;
    int left_child = node + 1;
    int right_child = node + 2 * (mid - left + 1);

    if (qr <= mid)
        return query(left_child, left, mid, ql, qr, out);
    if (ql > mid)
        return query(right_child, mid + 1, right, ql, qr, out);

    Node left_result, right_result;
    query(left_child, left, mid, ql, qr, &left_result);
    query(right_child, mid + 1, right, ql, qr, &right_result);
    merge_nodes(&left_result, &right_result, out);
    return 1;
}

int main(void) {
    int n, m;
    if (scanf("%d %d", &n, &m) != 2)
        return 0;

    int *values = (int *)malloc((size_t)n * sizeof(int));
    if (values == NULL)
        return 0;

    for (int i = 0; i < n; i++)
        scanf("%d", &values[i]);

    tree = (Node *)malloc((size_t)(2 * n) * sizeof(Node));
    if (tree == NULL) {
        free(values);
        return 0;
    }

    build(0, 0, n - 1, values);
    free(values);

    for (int i = 0; i < m; i++) {
        int type, x, y;
        scanf("%d %d %d", &type, &x, &y);

        if (type == 1) {
            update(0, 0, n - 1, x - 1, y);
        } else {
            Node result;
            query(0, 0, n - 1, x - 1, y - 1, &result);
            printf("%lld\n", result.good);
        }
    }

    free(tree);
    return 0;
}
